param(
  [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $Root ".orcaly-backups\checkout-cadastro-organizado-$Stamp"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

function Full([string]$Path) {
  Join-Path $Root ($Path -replace "/", "\")
}

function Backup-File([string]$Path) {
  $Source = Full $Path

  if (-not (Test-Path -LiteralPath $Source)) {
    return
  }

  $Destination = Join-Path $Backup ($Path -replace "/", "\")
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

function Write-Base64File(
  [string]$Path,
  [string]$Base64
) {
  $Target = Full $Path
  New-Item -ItemType Directory -Force -Path (Split-Path $Target -Parent) | Out-Null
  $Text = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64))
  [IO.File]::WriteAllText($Target, $Text.TrimEnd() + "`n", $Utf8)
  Write-Host "[OK] $Path" -ForegroundColor Green
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orcaly."
}

$Branch = (& git branch --show-current 2>$null | Out-String).Trim()

if ($Branch -ne "feature/asaas-sandbox") {
  throw "Branch atual: $Branch. Execute na branch feature/asaas-sandbox."
}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "ORCALY - CHECKOUT DE CADASTRO ORGANIZADO" -ForegroundColor Cyan
Write-Host "Pix interno + cartao + 7 dias somente no cadastro" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan

$Targets = @(
  "lib/signup-checkout.ts",
  "app/api/checkout/signup/route.ts",
  "app/api/checkout/signup/pix/route.ts",
  "app/api/checkout/signup/card/route.ts",
  "app/api/checkout/signup/status/route.ts",
  "app/checkout/cadastro/page.tsx",
  "components/checkout/SignupCheckout.tsx",
  "app/api/checkout/lead/route.ts",
  "app/api/mercado-pago/webhook-leads/route.ts",
  "app/api/leads/complete-account/route.ts",
  "components/subscription/MercadoPagoSubscriptionCheckout.tsx",
  "app/cadastro/page.tsx",
  "lib/subscription-mercado-pago-transparent.ts"
)

foreach ($Target in $Targets) {
  Backup-File $Target
}

$Files = @{
  "lib/signup-checkout.ts" = ""
  "app/api/checkout/signup/route.ts" = ""
  "app/api/checkout/signup/pix/route.ts" = ""
  "app/api/checkout/signup/card/route.ts" = ""
  "app/api/checkout/signup/status/route.ts" = ""
  "app/checkout/cadastro/page.tsx" = "aW1wb3J0IFNpZ251cENoZWNrb3V0IGZyb20gIkAvY29tcG9uZW50cy9jaGVja291dC9TaWdudXBDaGVja291dCI7CgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBTaWdudXBDaGVja291dFBhZ2UoKSB7CiAgcmV0dXJuIDxTaWdudXBDaGVja291dCAvPjsKfQ=="
  "components/checkout/SignupCheckout.tsx" = ""
  "app/api/checkout/lead/route.ts" = ""
  "app/api/mercado-pago/webhook-leads/route.ts" = ""
  "app/api/leads/complete-account/route.ts" = ""
  "components/subscription/MercadoPagoSubscriptionCheckout.tsx" = ""
}

foreach ($Entry in $Files.GetEnumerator()) {
  Write-Base64File $Entry.Key $Entry.Value
}

$PatcherPath = Join-Path $Root ".orcaly-patch-checkout-cadastro-$Stamp.cjs"
$PatcherCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)
[IO.File]::WriteAllText($PatcherPath, $PatcherCode, $Utf8)

try {
  Write-Host ""
  Write-Host "==> Ajustando cadastro e assinatura do painel" -ForegroundColor Cyan
  & node $PatcherPath

  if ($LASTEXITCODE -ne 0) {
    throw "O patcher nao conseguiu concluir as alteracoes."
  }
} finally {
  Remove-Item -LiteralPath $PatcherPath -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "==> Verificando referencias antigas no cadastro" -ForegroundColor Cyan

$Legacy = Select-String `
  -Path (Full "app/cadastro/page.tsx") `
  -Pattern "checkout_pro|paymentMode|Mercado Pago completo|Pix avulso" `
  -CaseSensitive:$false `
  -ErrorAction SilentlyContinue

if ($Legacy) {
  Write-Host "Ainda existem referencias antigas:" -ForegroundColor Red
  $Legacy | ForEach-Object {
    Write-Host "$($_.LineNumber): $($_.Line.Trim())"
  }
  throw "O cadastro ainda possui referencias ao Checkout Pro."
}

if (-not $SkipBuild) {
  Write-Host ""
  Write-Host "==> Executando build" -ForegroundColor Cyan

  & npm.cmd run build
  $BuildCode = $LASTEXITCODE

  Write-Host "BUILD_EXIT_CODE=$BuildCode"

  if ($BuildCode -ne 0) {
    Write-Host ""
    Write-Host "O build falhou. Nenhum commit foi criado." -ForegroundColor Red
    Write-Host "Backup: $Backup" -ForegroundColor Yellow
    exit $BuildCode
  }
}

Write-Host ""
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "CHECKOUT DE CADASTRO ATUALIZADO" -ForegroundColor Magenta
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "Cadastro: continua em pagina do Orcaly"
Write-Host "Pix: QR Code aparece somente depois da confirmacao"
Write-Host "Cartao: campos aparecem somente apos a escolha"
Write-Host "Cartao no cadastro: 7 dias sem cobranca"
Write-Host "Pix no cadastro: 30 dias pagos + 7 dias adicionais"
Write-Host "Painel de assinatura: sem novo periodo gratuito"
Write-Host "Backup: $Backup"
